\mathsf{RawPHole}
=
\{(E,\le_H,h,\lambda_H):
\begin{array}{l}
E=n,\ n\in\mathbb N_{>0},\ h\in n,\\
\le_H\text{ 是 }E\text{ 上的偏序},\\
\lambda_H:E\setminus\{h\}\to\mathsf{Frm}
\end{array}
\}.

\begin{aligned}
(0,e)\le'(0,e')&\Longleftrightarrow e\le_H e',\\
(1,f)\le'(1,f')&\Longleftrightarrow f\le_P f',\\
(0,e)\le'(1,f)&\Longleftrightarrow e\le_H h,\\
(1,f)\le'(0,e)&\Longleftrightarrow h\le_H e.
\end{aligned}

\mathsf{Rule}_{\multimap L}
=\{((P\Rightarrow A),(Q\parallel\langle B\rangle\Rightarrow C);
Q\parallel\langle\operatorname{limp}(A,B)\rangle\parallel P\Rightarrow C):
P,Q\in\mathsf{Pom},A,B,C\in\mathsf{Frm}\},

\mathsf{TreeCode}_{\mathsf{Pom}}
=\bigcup_{n\in\mathbb N,\ n>0}
\{n\}\times n\times\mathcal P(n\times n)
\times(n^{<\omega})^n\times(\mathsf{Seq})^n,
\qquad n^{<\omega}=\bigcup_{k\in\mathbb N}n^k.
